-- Summary
select count(*) as sba_count from public.questions where exam_id = 'a1000000-0000-4000-8000-000000000001' and question_type = 'sba' and is_active = true and coalesce(payload->>'source','') = 'plab1-xlsx-v6';
select t.name, count(*) as n from public.questions q left join public.topics t on t.id = q.topic_id where q.exam_id = 'a1000000-0000-4000-8000-000000000001' and coalesce(q.payload->>'source','') = 'plab1-xlsx-v6' group by t.name order by n desc;
select count(*) as with_image from public.questions where exam_id = 'a1000000-0000-4000-8000-000000000001' and coalesce(payload->>'source','') = 'plab1-xlsx-v6' and coalesce(payload->>'image_url','') <> '';
