  ('26c5bfac-e927-56a8-8790-e01dd3208a4c', '7562a5cf-3148-5000-a21e-f185b89869df', 'A', 'Kidney stones only', false, 0),
  ('eb831bf0-046a-5c42-8f98-33f329fdc507', '7562a5cf-3148-5000-a21e-f185b89869df', 'B', 'No concern', false, 1),
