  ('c0c7a6f2-802a-5d6d-a757-e6dcf215652e', 'ccda6b83-4dcf-5e96-8f0a-f469cdd7f8e4', 'B', 'Air enema reduction', false, 1),
  ('9768b013-0098-5a7e-8314-692d06de4b70', 'ccda6b83-4dcf-5e96-8f0a-f469cdd7f8e4', 'C', 'Laxatives', false, 2),
