  ('62211c74-af38-5928-b037-0528da11bb12', 'a69fdcbf-f99b-5671-aaef-68073cb0f836', 'B', 'Glaucoma', false, 1),
  ('f7f4d5e9-cdbd-5a72-9575-9758c0ffa9ea', 'a69fdcbf-f99b-5671-aaef-68073cb0f836', 'C', 'Retinal detachment', false, 2),
