  ('621155ff-503e-5720-a143-8edbb1e4acaf', '021aafed-c7c3-5f88-85c2-ecfc8e9f85ac', 'B', 'TB', false, 1),
  ('58b9e123-f673-53a5-a7e0-161b2968b4b3', '021aafed-c7c3-5f88-85c2-ecfc8e9f85ac', 'C', 'Inflammatory bowel disease', false, 2),
