  ('0c67a580-c48a-5930-ac8b-5b54c583c58a', 'd9936eba-b1f6-5159-ae7b-cff19ae8816e', 'B', 'MCL rupture', false, 1),
  ('8c0306c9-fd96-576d-ad2c-4d1e2cafed68', 'd9936eba-b1f6-5159-ae7b-cff19ae8816e', 'C', 'Medial meniscal tear', false, 2),
