  ('ec92d77c-90c7-5305-b399-d8b609c11074', 'e32df246-0b13-51bf-b948-e30081690cf0', 'B', 'Hydrocele', false, 1),
  ('0aa20b24-aebd-50f8-b230-666031ef1ffe', 'e32df246-0b13-51bf-b948-e30081690cf0', 'C', 'Inguinal hernia', false, 2),
