  ('628478c5-d4ac-5d30-8ad8-6caca081dd25', 'a7ce434c-576a-55b2-b2bc-523480f8d0a9', 'A', 'Oral sildenafil', false, 0),
  ('f25b0e76-799e-542a-8ce1-9ca2f89c8654', 'a7ce434c-576a-55b2-b2bc-523480f8d0a9', 'B', 'Ice packs only', false, 1),
