  ('96fe2e16-86e0-5434-a875-4d15c5f1b710', '15e7ef9e-63c6-566a-b39e-02ce0257076a', 'A', 'Oral diazepam', false, 0),
  ('271c6358-2fc6-5fd4-b592-7f5e148be438', '15e7ef9e-63c6-566a-b39e-02ce0257076a', 'B', 'Chlorpromazine IM', false, 1),
