  ('b74400ea-f956-5d67-a152-5f91d8fe8496', 'cc82b434-287e-51f4-9a7f-02b22e0209e2', 'A', 'Abdominal ultrasound', true, 0),
  ('29743825-df68-58f5-b17e-c276029016fc', 'cc82b434-287e-51f4-9a7f-02b22e0209e2', 'B', 'ERCP', false, 1),
