  ('a4216063-8286-53ab-b282-c1a93d5f1ba0', '68348bfb-87fb-552b-a96c-934a73987ee7', 'A', 'Thyroid cancer', false, 0),
  ('44ed4f80-7eb2-5c2b-9771-588f0106307a', '68348bfb-87fb-552b-a96c-934a73987ee7', 'B', 'Hashimoto''s', false, 1),
