  ('b41047eb-c044-5051-ab83-c818b51ec932', '8c9c0f03-6948-5f3a-8b78-e60b9532941c', 'A', '45,XO', false, 0),
  ('4d79d401-78bd-51fd-a71d-3f47b3bc8107', '8c9c0f03-6948-5f3a-8b78-e60b9532941c', 'B', '46,XY', false, 1),
