  ('146cf259-4ad2-5039-bd2b-59402085811c', 'e260b210-593f-5eb6-953e-d74085bba035', 'A', 'Cross-monitoring', false, 0),
  ('57770c81-3977-5315-aab8-3a10ade871af', 'e260b210-593f-5eb6-953e-d74085bba035', 'B', 'Debrief', false, 1),
